<script setup>
import {ref,computed} from 'vue'
import {missions} from './missions.js'
import {state} from './store.js'
const selected=ref(0),request=ref({...missions[0].request}),logs=ref([]),hypothesis=ref(''),notes=ref(''),hint=ref(0),revealed=ref(false),saved=ref(false)
const mission=computed(()=>missions[selected.value])
const observations=computed(()=>new Set(logs.value.map(l=>l.evidence).filter(Boolean)))
const demonstrated=computed(()=>mission.value.id==='media-chain'?observations.value.has('discovery')&&observations.value.has('internal-fetch'):observations.value.size>0)
const canSave=computed(()=>demonstrated.value&&hypothesis.value.trim().length>=15&&notes.value.trim().length>=25)
function change(){request.value={...mission.value.request};logs.value=[];hypothesis.value='';notes.value='';hint.value=0;revealed.value=false;saved.value=false}
function send(){try{const known=mission.value.routes.some(route=>route.split(' ')[1].split('?')[0]===request.value.path.split('?')[0]);const result=known?mission.value.run(request.value):{trace:'No route matched the request.',output:'404: route absent from this workspace',explanation:'Compare the requested path with the observed route inventory.'};logs.value.push({...result,request:{...request.value},index:logs.value.length+1});saved.value=false}catch(e){logs.value.push({trace:'Request did not reach the modeled operation.',output:e.message,explanation:'Check the input type and the request inventory.',request:{...request.value},index:logs.value.length+1})}}
function save(){if(!canSave.value)return;state.missions[mission.value.id]=true;state.notes['mission:'+mission.value.id]=`Hypothesis: ${hypothesis.value}\n\nEvidence and limits:\n${notes.value}\n\nRecorded requests:\n${logs.value.map(l=>`${l.request.path}: ${l.request.input}\n${l.output}`).join('\n\n')}`.slice(0,20000);saved.value=true}
</script>
<template><section class="investigation-desk"><div class="desk-intro"><label class="select-label">Fictional workspace<select v-model="selected" @change="change"><option v-for="(m,i) in missions" :value="i" :key="m.id">{{m.title}}{{state.missions[m.id]?' · evidence recorded':''}}</option></select></label><span class="eyebrow">LOCAL INVESTIGATION · NO LAB TARGET</span></div><h2>{{mission.title}}</h2><p class="case-scene">{{mission.scene}}</p><details class="desk-inventory" open><summary>Observed routes</summary><code v-for="route in mission.routes" :key="route">{{route}}</code></details><div class="desk-workspace"><form @submit.prevent="send"><h3>Replay a request</h3><label for="desk-session">Session / actor</label><input id="desk-session" v-model="request.session" :readonly="mission.id!=='receipts'" maxlength="80"><label for="desk-path">Path</label><input id="desk-path" v-model="request.path" maxlength="400"><label for="desk-input">Input value / body</label><textarea id="desk-input" v-model="request.input" rows="3" maxlength="3000" spellcheck="false"></textarea><button class="button primary" type="submit">Send to local fixture →</button><p class="fine-print">No suggested exploit payloads. Change one condition and record what it establishes.</p></form><div class="desk-log"><h3>Evidence log <span>{{logs.length}}</span></h3><p v-if="!logs.length" class="muted">Send a baseline first. Each response will appear here for comparison.</p><details v-for="log in [...logs].reverse()" :key="log.index" :open="log.index===logs.length"><summary>Request {{log.index}} · {{log.request.path}}</summary><strong>Request input</strong><pre>{{log.request.input}}</pre><strong>Observation</strong><pre>{{log.output}}</pre><details class="teaching-trace"><summary>Reveal teaching trace</summary><pre>{{log.trace}}</pre><p>{{log.explanation}}</p></details></details></div></div><div class="desk-notebook"><h3>Make your reasoning inspectable.</h3><label for="desk-hypothesis">What boundary are you testing?</label><textarea id="desk-hypothesis" v-model="hypothesis" maxlength="3000" rows="2" placeholder="I think this service trusts…"></textarea><label for="desk-notes">Your control, evidence, alternative explanation, and proposed fix</label><textarea id="desk-notes" v-model="notes" maxlength="10000" rows="4" placeholder="What changed? What did you observe? What does it prove—and what remains unproven?"></textarea><button class="button primary" :disabled="!canSave" @click="save">Save investigation record</button><p class="fine-print" role="status">{{saved?'Record saved with your notes. Revisit it and challenge your explanation.':demonstrated?'The fixture observed a relevant boundary effect. Explain it before saving.':'No relevant boundary effect has been demonstrated yet. Keep your baseline and test one hypothesis.'}}</p></div><details class="desk-help"><summary>Need a nudge?</summary><p v-if="hint===0">Start with a normal request. Inspect the session, object or path, parser, and any server-side request. Write the observation you expect before changing one field.</p><p v-else>{{mission.hypothesis}}. What two requests would distinguish correct enforcement from misplaced trust?</p><button v-if="hint===0" class="quiet-button" @click="hint++">Focus the next hypothesis →</button><button class="quiet-button" @click="revealed=!revealed">{{revealed?'Hide':'Reveal'}} related learning →</button><a v-if="revealed" class="button" :href="`#/learn/${mission.module}/0`">Study the related mechanism ↗</a></details><p class="fine-print">Recording evidence is not automatic grading of your prose or proof of readiness for every CTF. These workspaces are separate from your Academy lab completion.</p></section></template>
